<section class="page-intro"><p class="eyebrow">THE WIKI WARDROBE</p><h1><?=e($path==='/scents'?'Find your signature.':($path==='/clothing'?'Everyday, elevated.':($path==='/collections'?'The considered collections.':'Good things, thoughtfully chosen.')))?></h1><p>Discover the pieces and scents that feel like you.</p></section>
<section class="section shop-section"><form class="filter-bar" method="get" action="<?=e($path)?>" id="filters"><label class="search-field"><span class="sr-only">Search products</span><input type="search" name="q" placeholder="Search by name, SKU, or story…" value="<?=e($filters['q']??'')?>"></label><label>Category<select name="category"><option value="">All categories</option><?php foreach(query('SELECT name,slug FROM categories ORDER BY name')->fetchAll() as $c): ?><option value="<?=e($c['slug'])?>" <?=($filters['category']??'')===$c['slug']?'selected':''?>><?=e($c['name'])?></option><?php endforeach ?></select></label><label>Sort by<select name="sort"><?php foreach(['featured'=>'Featured','newest'=>'Newest','price-asc'=>'Price: low to high','price-desc'=>'Price: high to low','rating'=>'Highest rated','best'=>'Best selling'] as $value=>$label): ?><option value="<?=e($value)?>" <?=($filters['sort']??'featured')===$value?'selected':''?>><?=e($label)?></option><?php endforeach ?></select></label><button class="btn">Find your edit ↗</button><details class="more-filters"><summary>More filters +</summary><div class="filter-fields"><?php foreach(['min'=>'Min price (PKR)','max'=>'Max price (PKR)'] as $key=>$label): ?><label><?=e($label)?><input type="number" name="<?=e($key)?>" min="0" value="<?=e($filters[$key]??'')?>"></label><?php endforeach ?><?php foreach(['size'=>['XS','S','M','L','XL','XXL'],'color'=>['Black','White','Navy','Beige','Brown','Grey'],'volume'=>['30ml','50ml','100ml'],'family'=>['Fresh','Woody','Floral','Oriental','Citrus'],'rating'=>['1','2','3','4','5']] as $key=>$values): ?><label><?=e(ucfirst($key))?><select name="<?=e($key)?>"><option value="">Any</option><?php foreach($values as $v): ?><option <?=($filters[$key]??'')===$v?'selected':''?>><?=e($v)?></option><?php endforeach ?></select></label><?php endforeach ?><label class="check"><input type="checkbox" name="available" value="1" <?=!empty($filters['available'])?'checked':''?>> In stock</label><label class="check"><input type="checkbox" name="sale" value="1" <?=!empty($filters['sale'])?'checked':''?>> On sale</label></div></details><?php if(isset($filters['type'])): ?><input type="hidden" name="type" value="<?=e($filters['type'])?>"><?php endif ?></form><div class="results-note" aria-live="polite" id="results-note"><?=count($products)?> pieces in this edit</div><div class="product-grid" id="product-results"><?php foreach($products as $item) require ROOT.'/views/partials/card.php'; ?></div><p id="empty-results" <?=count($products)?'hidden':''?>>No matches yet. Try another search or remove a filter.</p><nav class="pagination" aria-label="Product pages"><?php $pg=max(1,(int)($filters['page']??1)); if($pg>1): ?><a class="btn secondary" href="?<?=e(http_build_query(array_merge($filters,['page'=>$pg-1])))?>">← Previous</a><?php endif ?><span>Page <?=e($pg)?></span><?php if(count($products)===12): ?><a class="btn secondary" href="?<?=e(http_build_query(array_merge($filters,['page'=>$pg+1])))?>">Next →</a><?php endif ?></nav></section>
